import express from "express";
import { isAuth, isSeller } from "../middlewares/auth.js";
import { addMenuItem, getAllItems, getSingleItem, updateMenuItem, deleteMenuItem, toggleAvailability, searchMenuItems } from "../controller/menuItem.js";
import uploadFile from "../middlewares/multer.js";
const router = express.Router();
router.post("/add", isAuth, isSeller, uploadFile, addMenuItem);
router.get("/all/:id", isAuth, isSeller, getAllItems);
router.get("/single/:id", isAuth, isSeller, getSingleItem);
router.get("/search/:restaurantId", isAuth, isSeller, searchMenuItems);
router.put("/update/:id", isAuth, isSeller, uploadFile, updateMenuItem);
router.delete("/delete/:id", isAuth, isSeller, deleteMenuItem);
router.patch("/toggle-availability/:id", isAuth, isSeller, toggleAvailability);
export default router;
